import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

import { describeSample2NameState } from "../app/use-case.ts";
import { initialSample2NameState } from "../domain/types.ts";
import { renderSample2NameStatus } from "../ui/render.ts";

export function registerSample2Name(pi: ExtensionAPI): void {
  pi.on("session_start", (_event, ctx) => {
    const text = renderSample2NameStatus(describeSample2NameState(initialSample2NameState));
    ctx.ui.setStatus("sample-2-name", text);
  });
}

export function renderSample2NameStatus(text: string): string {
  return `Sample 2 Name ${text}`.trim();
}

